      PLASTER=9, TIMBER=10, BARNRED=11, STONEBRICK=12, R_TERRA=13, R_SLATE=14,
      R_THATCH=15, R_DARK=16, PATH=17, GLOW=18, FLOWER=19;
const MATS = [];
