defM(GRASS,0x7da44e,{v:.10});  defM(DIRT,0x8a684a,{v:.07});   defM(STONE,0x8b8b90,{v:.06});
defM(SAND,0xdcc98e,{v:.06});   defM(WATER,0x4e97cf,{o:.82,v:.05}); defM(WOOD,0x7c5a36,{v:.06});
defM(DARKWOOD,0x4a3624,{v:.05});defM(LEAF,0x5d9b41,{v:.13});  defM(PINE,0x3e7050,{v:.10});
defM(PLASTER,0xefe5cb,{v:.035});defM(TIMBER,0x6b4b2e,{v:.05}); defM(BARNRED,0x9a4531,{v:.05});
defM(STONEBRICK,0xa79f90,{v:.07});defM(R_TERRA,0xb6563a,{v:.05});defM(R_SLATE,0x5c7285,{v:.05});
defM(R_THATCH,0xc9a455,{v:.08});defM(R_DARK,0x57432f,{v:.05}); defM(PATH,0xa89f8d,{v:.10});
