/* ---------------- deterministic randomness ---------------- */
function mulberry32(a){return function(){a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);
  t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};}
const rng   = mulberry32(20240607);
const hash2 = (x,z)=>{const s=Math.sin(x*127.1+z*311.7)*43758.5453;return s-Math.floor(s);};
const hash3 = (x,y,z)=>{const s=Math.sin(x*127.1+y*269.5+z*419.2)*43758.5453;return s-Math.floor(s);};

/* ---------------- terrain: 64x64 columns, hills + river valley ---------------- */
const SIZE=64, OFF=32, WL=4;
const idx   = (x,z)=>z*SIZE+x;
const height= new Int16Array(SIZE*SIZE);
const topM  = new Uint8Array(SIZE*SIZE);
const riverZ= x => 8.5 + 5.2*Math.sin(x*0.048+0.8) + 2.6*Math.sin(x*0.016+2.2);
function baseH(x,z){
  let h = 8.2
    + 3.4*Math.sin(x*0.072+1.1)*Math.cos(z*0.066-0.7)
    + 2.1*Math.sin(x*0.043+z*0.055+2.3)
    + 1.1*Math.cos((x-z)*0.085+0.5);
  h += 4.6*Math.exp(-((x-46)*(x-46)+(z-55)*(z-55))/130);  // south hill
  h += 3.0*Math.exp(-((x-9)*(x-9)+(z-52)*(z-52))/110);    // west hill
  h += 2.4*Math.exp(-((x-56)*(x-56)+(z-10)*(z-10))/120);  // north-east rise
  return h;
}
function terrainH(x,z){
  const d=Math.abs(z-riverZ(x)), R=6.2;
  let h=baseH(x,z);
  if(d<R){ const t=1-d/R, s=t*t*(3-2*t); h=h*(1-s)+(WL-2.1)*s; } // carve the river valley
  return Math.max(1, Math.round(h));
}
for(let z=0;z<SIZE;z++)for(let x=0;x<SIZE;x++){
  const h=terrainH(x,z);
  height[idx(x,z)]=h;
  topM[idx(x,z)] = h<=WL ? SAND : GRASS;
}

/* ---------------- village layout ---------------- */
const PC={x:32,z:34};                 // plaza center
const PL={x0:28,x1:36,z0:30,z1:38};   // paved plaza rect
const B=[ // 13 structures, 5 designs + market stall
  {t:'cottage',x0:20,z0:32,w:5,d:5,door:'+x',roof:R_TERRA ,chim:true ,xf:true },
  {t:'cottage',x0:40,z0:32,w:5,d:5,door:'-x',roof:R_TERRA ,chim:true ,xf:true },
  {t:'house'  ,x0:29,z0:21,w:6,d:6,door:'+z',roof:R_SLATE ,chim:true ,xf:false},
