  {t:'long'   ,x0:39,z0:40,w:5,d:7,ridge:'z',door:'-x',roof:R_DARK,xf:true},
  {t:'tower'  ,x0:48,z0:52,w:4,d:4,door:'-x',roof:R_DARK ,xf:true },
  {t:'cottage',x0:41,z0:49,w:4,d:4,door:'-x',roof:R_THATCH,chim:true,xf:true},
  {t:'barn'   ,x0:8 ,z0:32,w:8,d:6,door:'+x',roof:R_TERRA ,wall:WOOD,xf:true},
  {t:'cottage',x0:48,z0:36,w:5,d:5,door:'-x',roof:R_TERRA ,chim:false,xf:true},
  {t:'stall'  ,x0:24,z0:28,w:3,d:3,door:'+x',xf:true},
];
function doorCells(b){
  const x1=b.x0+b.w-1, z1=b.z0+b.d-1; let dx,dz,ox,oz;
  if(b.door==='+x'){dx=x1;   dz=b.z0+(b.d>>1); ox=dx+1; oz=dz;}
  else if(b.door==='-x'){dx=b.x0; dz=b.z0+(b.d>>1); ox=dx-1; oz=dz;}
