}

/* flatten building plots (+1-cell apron) and the plaza so nothing floats or sinks */
let PH=WL+2;
for(let z=PL.z0;z<=PL.z1;z++)for(let x=PL.x0;x<=PL.x1;x++)PH=Math.max(PH,height[idx(x,z)]);
