  const rx0=Math.max(0,b.x0-1),rx1=Math.min(SIZE-1,b.x0+b.w),
        rz0=Math.max(0,b.z0-1),rz1=Math.min(SIZE-1,b.z0+b.d);
  let H=WL+2;
  for(let z=rz0;z<=rz1;z++)for(let x=rx0;x<=rx1;x++)H=Math.max(H,height[idx(x,z)]);
  b.H=H;
  for(let z=rz0;z<=rz1;z++)for(let x=rx0;x<=rx1;x++){height[idx(x,z)]=H; topM[idx(x,z)]=GRASS;}
}
for(let z=PL.z0;z<=PL.z1;z++)for(let x=PL.x0;x<=PL.x1;x++){height[idx(x,z)]=PH; topM[idx(x,z)]=GRASS;}

/* ---------------- stone paths: every door -> plaza hub ---------------- */
const pathCells=new Set();
function markPath(x,z){
  if(x<0||x>=SIZE||z<0||z>=SIZE)return;
  if(x>=PL.x0&&x<=PL.x1&&z>=PL.z0&&z<=PL.z1)return;
  const i=idx(x,z);
  if(height[i]<=WL)return;            // never pave water
  topM[i]=PATH; pathCells.add(x+','+z);
}
for(const b of B){
  const {ox,oz}=doorCells(b);
  let x=ox,z=oz,g=0;
