    else    { if(z!==PC.z)z+=Math.sign(PC.z-z); else if(x!==PC.x)x+=Math.sign(PC.x-x); else break; }
  }
}
for(let z=PL.z0;z<=PL.z1;z++)for(let x=PL.x0;x<=PL.x1;x++){topM[idx(x,z)]=PATH;pathCells.add(x+','+z);}

/* ---------------- voxel world map ---------------- */
const world=new Map();
let maxY=1;
const K=(x,y,z)=>x+(z<<7)+(y<<14);
const setV=(x,y,z,id)=>{world.set(K(x,y,z),id); if(y+1>maxY)maxY=y+1;};
const getV=(x,y,z)=>world.get(K(x,y,z));
const chimneys=[];

function addStall(b){
  const H=b.H,x0=b.x0,z0=b.z0,x1=x0+b.w-1,z1=z0+b.d-1;
  for(const[px,pz]of[[x0,z0],[x1,z0],[x0,z1],[x1,z1]]){setV(px,H,pz,DARKWOOD);setV(px,H+1,pz,DARKWOOD);}
  for(let x=x0-1;x<=x1+1;x++)for(let z=z0-1;z<=z1+1;z++)setV(x,H+2,z,R_TERRA);
  setV(x0+1,H,z0+1,WOOD); setV(x0+1,H+1,z0+1,WOOD);
  setV(x0+1,H+1,z0-1,GLOW); setV(x0+1,H+1,z1+1,GLOW);
}
function addBuilding(b){
  if(b.t==='stall'){addStall(b);return;}
  const H=b.H,x0=b.x0,z0=b.z0,x1=x0+b.w-1,z1=z0+b.d-1;
  const wall=b.wall!==undefined?b.wall:(b.t==='tower'?STONEBRICK:b.t==='long'?TIMBER:PLASTER);
  const trim=(b.t==='cottage'||b.t==='house')?TIMBER:b.t==='barn'?DARKWOOD:undefined;
  const wallH=b.t==='tower'?7:(b.t==='house'||b.t==='barn')?4:3;
  for(let y=H;y<H+wallH;y++)
    for(let x=x0;x<=x1;x++)for(let z=z0;z<=z1;z++){
      if(x!==x0&&x!==x1&&z!==z0&&z!==z1)continue;
      const corner=(x===x0||x===x1)&&(z===z0||z===z1);
      setV(x,y,z, corner&&trim!==undefined?trim:wall);
    }
  const {dx,dz}=doorCells(b);
  const dw=b.t==='barn'?2:1, doorSet=new Set();
  for(let i=0;i<dw;i++){
    if(b.door==='+x'||b.door==='-x'){setV(dx,H,dz+i,DARKWOOD);setV(dx,H+1,dz+i,DARKWOOD);doorSet.add(dx+','+(dz+i));}
    else{setV(dx+i,H,dz,DARKWOOD);setV(dx+i,H+1,dz,DARKWOOD);doorSet.add((dx+i)+','+dz);}
  }
  const rows=b.t==='tower'?[1,3,5]:(wallH>=4?[1,3]:[1]);
  for(const s of ['+x','-x','+z','-z']){
    const cells=[];
    if(s==='+x')for(let z=z0+1;z<z1;z++)cells.push([x1,z]);
    else if(s==='-x')for(let z=z0+1;z<z1;z++)cells.push([x0,z]);
    else if(s==='+z')for(let x=x0+1;x<x1;x++)cells.push([x,z1]);
    else for(let x=x0+1;x<x1;x++)cells.push([x,z0]);
