      for(let x=ax0;x<=ax1;x++)for(let z=az0;z<=az1;z++)setV(x,y,z,b.roof);
    }
  }else{                                       // stepped gable roof (ridge along x or z)
    const alongX=(b.ridge||'x')==='x';
    const levels=Math.ceil(((alongX?b.d:b.w)+2)/2);
    for(let r=0;r<levels;r++){
      let ax0,ax1,az0,az1;
      if(alongX){ax0=x0-(r===0?1:0);ax1=x1+(r===0?1:0);az0=z0-1+r;az1=z1+1-r;}
      else{az0=z0-(r===0?1:0);az1=z1+(r===0?1:0);ax0=x0-1+r;ax1=x1+1-r;}
      if(az1<az0||ax1<ax0)break;
      const y=H+wallH+r; roofTop=y;
      for(let x=ax0;x<=ax1;x++)for(let z=az0;z<=az1;z++)setV(x,y,z,b.roof);
    }
  }
  if(b.chim){
    const cx=x0+1,cz=z0+1;
    for(let y=H+wallH;y<=roofTop+1;y++)setV(cx,y,cz,STONEBRICK);
    chimneys.push({gx:cx,gz:cz,y:roofTop+2});
  }
}
for(const b of B)addBuilding(b);

/* village well on the plaza */
(function addWell(){
  const cx=PC.x,cz=PC.z,H=PH;
  height[idx(cx,cz)]=H-2; topM[idx(cx,cz)]=SAND;
  for(let dx2=-1;dx2<=1;dx2++)for(let dz2=-1;dz2<=1;dz2++){
    if(dx2===0&&dz2===0)continue;
    setV(cx+dx2,H,cz+dz2,STONEBRICK); setV(cx+dx2,H+1,cz+dz2,STONEBRICK);
  }
  for(const px of [cx-1,cx+1])for(let y=H+2;y<=H+4;y++)setV(px,y,cz,DARKWOOD);
  for(let x=cx-2;x<=cx+2;x++)for(let z=cz-1;z<=cz+1;z++)setV(x,H+5,z,R_DARK);
  for(let x=cx-2;x<=cx+2;x++)setV(x,H+6,cz,R_DARK);
  setV(cx,H-2,cz,WATER); setV(cx,H-1,cz,WATER);
})();

/* lamp posts (lantern voxels glow at night) */
const lampPos=[[29,31],[35,31],[29,37],[35,37],[39,52],[33,28]];
for(const [lx,lz] of lampPos){
  const h=height[idx(lx,lz)];
  for(let y=h;y<=h+2;y++)setV(lx,y,lz,DARKWOOD);
  setV(lx,h+3,lz,GLOW); setV(lx,h+4,lz,DARKWOOD);
}

/* ---------------- trees / greenery ---------------- */
function farFromBuildings(x,z,pad){
  for(const b of B)
    if(x>=b.x0-pad&&x<=b.x0+b.w-1+pad&&z>=b.z0-pad&&z<=b.z0+b.d-1+pad)return false;
  if(x>=PL.x0-pad&&x<=PL.x1+pad&&z>=PL.z0-pad&&z<=PL.z1+pad)return false;
  return true;
}
const layer3=(cx,cy,cz,m)=>{for(let dx=-1;dx<=1;dx++)for(let dz=-1;dz<=1;dz++)if(!getV(cx+dx,cy,cz+dz))setV(cx+dx,cy,cz+dz,m);};
const plus5 =(cx,cy,cz,m)=>{for(const[dx,dz]of[[0,0],[1,0],[-1,0],[0,1],[0,-1]])if(!getV(cx+dx,cy,cz+dz))setV(cx+dx,cy,cz+dz,m);};
const layer5=(cx,cy,cz,m,skip)=>{for(let dx=-2;dx<=2;dx++)for(let dz=-2;dz<=2;dz++){
  if(dx===0&&dz===0)continue;
  if(Math.abs(dx)===2&&Math.abs(dz)===2&&(skip?hash3(cx+dx,cy,cz+dz)<0.55:true))continue;
  if(!getV(cx+dx,cy,cz+dz))setV(cx+dx,cy,cz+dz,m);}};

const treePts=[];
{ let placed=0,g=0;
  while(placed<30&&g++<5000){
    const x=2+Math.floor(rng()*(SIZE-4)), z=2+Math.floor(rng()*(SIZE-4));
    const i=idx(x,z), h=height[i];
    if(topM[i]!==GRASS||h<=WL+1)continue;
    if(!farFromBuildings(x,z,2))continue;
    if(pathCells.has(x+','+z))continue;
    if(getV(x,h,z)!==undefined)continue;
    let near=false;
    for(const t of treePts)if(Math.abs(t.x-x)<3&&Math.abs(t.z-z)<3){near=true;break;}
    if(near)continue;
    treePts.push({x,z,h,pine:rng()<0.32,s:rng()}); placed++;
  }
}
for(const t of treePts){
  const {x,z,h}=t, th=t.pine?5+(t.s*2|0):3+(t.s*2|0), ty=h+th-1;
  for(let y=h;y<=ty;y++)setV(x,y,z,WOOD);
  if(t.pine){ layer5(x,ty-2,z,PINE,true); layer3(x,ty-1,z,PINE); plus5(x,ty,z,PINE); if(!getV(x,ty+1,z))setV(x,ty+1,z,PINE); }
  else      { layer5(x,ty-1,z,LEAF,true); layer5(x,ty,z,LEAF,true); layer3(x,ty+1,z,LEAF); plus5(x,ty+2,z,LEAF); }
}
const flowerPal=[0xd05a48,0xe3b83f,0xf2ead8];
function scatter(count,test,place){
  let n=0,g=0;
  while(n<count&&g++<3000){
    const x=2+Math.floor(rng()*(SIZE-4)), z=2+Math.floor(rng()*(SIZE-4));
    const i=idx(x,z), h=height[i];
    if(!test(x,z,h,i))continue;
    place(x,z,h); n++;
  }
}
const freeSpot=(x,z,h,i)=>topM[i]===GRASS&&h>WL+1&&farFromBuildings(x,z,1)&&!pathCells.has(x+','+z)&&!getV(x,h,z);
scatter(16,freeSpot,(x,z,h)=>{setV(x,h,z,LEAF); if(rng()<0.3&&!getV(x,h+1,z))setV(x,h+1,z,LEAF);});
scatter(16,freeSpot,(x,z,h)=>setV(x,h,z,FLOWER));
scatter(9,(x,z,h,i)=>(topM[i]===GRASS||topM[i]===SAND)&&h>WL&&farFromBuildings(x,z,1)&&!pathCells.has(x+','+z)&&!getV(x,h,z),
