  for(let n=0;n<6;n++){
    const nx=x+NB[n][0], ny=y+NB[n][1], nz=z+NB[n][2];
    let blk;
    if(ny<0)blk=true;
    else if(nx<0||nx>=SIZE||nz<0||nz>=SIZE)blk=false;
    else{const nid=world.get(K(nx,ny,nz)); blk=nid!==undefined&&(selfW||nid!==WATER);}
    if(!blk){exp=true;break;}
  }
  if(exp)buckets[id].push(x,y,z);
}
const boxGeo=new THREE.BoxGeometry(1,1,1);
const dummy=new THREE.Object3D();
