      if(id===GRASS&&hash3(x*7,y,z*3)<0.06)cTmp.offsetHSL(0.02,0.03,0.05);
      if(id===PATH&&((x+z)&1)===0)cTmp.multiplyScalar(0.93);
      mesh.setColorAt(i,cTmp);
    }
  }
