/* ---------------- day / night ---------------- */
const ENV={skyTopD:0x58a4de,skyTopN:0x0a1228, skyBotD:0xd9eaf0,skyBotN:0x1d2c4e,
  hemiSD:0xd2e9ff,hemiSN:0x33406b, hemiGD:0x8c9a66,hemiGN:0x1b2231,
  sunD:0xffedd0,sunN:0xa9bfff, glowD:0x3a5568,glowN:0xffc46a,
  waterD:0x4e97cf,waterN:0x2a4d74, cloudD:0xffffff,cloudN:0x5f6a86,
  cloudED:0x000000,cloudEN:0x0e1626, sunMD:0xfff3c0,sunMN:0xe9eeff,
  smokeD:0xc7cbd1,smokeN:0x3c4452};
const _ca=new THREE.Color(), _cb=new THREE.Color();
const LC=(tg,a,b,e)=>{_ca.setHex(a);_cb.setHex(b);tg.copy(_ca).lerp(_cb,e);};
let mix=0, mixTarget=0, elT=0;
function applyEnv(e){
  LC(skyUni.top.value,ENV.skyTopD,ENV.skyTopN,e);
  LC(skyUni.bot.value,ENV.skyBotD,ENV.skyBotN,e);
  scene.fog.color.copy(skyUni.bot.value);
  scene.fog.near=THREE.MathUtils.lerp(130,80,e);
  scene.fog.far =THREE.MathUtils.lerp(360,240,e);
