  LC(hemi.groundColor,ENV.hemiGD,ENV.hemiGN,e);
  hemi.intensity=THREE.MathUtils.lerp(0.95,0.34,e);
  LC(sun.color,ENV.sunD,ENV.sunN,e);
  sun.intensity=THREE.MathUtils.lerp(1.5,0.42,e);
  sun.position.lerpVectors(sunDay,sunNight,e);
  if(glowMat){ LC(glowMat.color,ENV.glowD,ENV.glowN,e);
    glowMat.color.multiplyScalar(1+e*(0.04*Math.sin(elT*2.1)+0.03*Math.sin(elT*5.3))); }
  if(waterMat){ LC(waterMat.color,ENV.waterD,ENV.waterN,e); LC(waterMat.emissive,0x000000,0x0d2033,e); }
  LC(cloudMat.color,ENV.cloudD,ENV.cloudN,e);
  LC(cloudMat.emissive,ENV.cloudED,ENV.cloudEN,e);
  LC(sunMesh.material.color,ENV.sunMD,ENV.sunMN,e);
  sunMesh.scale.setScalar(THREE.MathUtils.lerp(1,0.7,e));
  sunMesh.position.copy(sun.position).normalize().multiplyScalar(415);
  starMat.opacity=e;
  for(const L of lampLights)L.intensity=30*e;
  LC(smokeMat.color,ENV.smokeD,ENV.smokeN,e);
  renderer.toneMappingExposure=THREE.MathUtils.lerp(1.05,0.9,e);
}

/* ---------------- HUD: badge + toast ---------------- */
const badge=document.getElementById('badge'), badgeLabel=document.getElementById('badgeLabel'),
      icoSun=document.getElementById('icoSun'), icoMoon=document.getElementById('icoMoon'),
