/* ---------------- orbit camera (auto-rotate + drag + zoom, auto-framed) ---------------- */
const target=new THREE.Vector3(PC.x+0.5-OFF, PH+2, PC.z+0.5-OFF);
let theta=0.85, el=0.55, elOff=0, zoom=1, distCur=340;
const fitPts=[];
{ const xs=[-OFF,OFF], ys=[0,maxY], zs=[-OFF,OFF];
  for(const x of xs)for(const y of ys)for(const z of zs)fitPts.push(new THREE.Vector3(x,y,z)); }
function placeCamera(d){
  const cp=Math.cos(el);
  camera.position.set(target.x+Math.cos(theta)*cp*d, target.y+Math.sin(el)*d, target.z+Math.sin(theta)*cp*d);
  camera.lookAt(target);
  camera.updateMatrixWorld();
  camera.matrixWorldInverse.copy(camera.matrixWorld).invert();
}
const _fr=new THREE.Frustum(), _m4=new THREE.Matrix4();
function computeFit(){ // smallest distance at which the whole world box stays inside the frustum
  let lo=25, hi=520;
  for(let i=0;i<17;i++){
    const mid=(lo+hi)*0.5;
    placeCamera(mid);
    _m4.multiplyMatrices(camera.projectionMatrix, camera.matrixWorldInverse);
    _fr.setFromProjectionMatrix(_m4);
    let ok=true;
    for(const p of fitPts)if(!_fr.containsPoint(p)){ok=false;break;}
    if(ok)hi=mid; else lo=mid;
  }
  return hi;
}
let dragging=false, pxx=0, pyy=0;
const cv=renderer.domElement;
cv.addEventListener('pointerdown',e=>{dragging=true;pxx=e.clientX;pyy=e.clientY;cv.setPointerCapture(e.pointerId);});
addEventListener('pointermove',e=>{ if(!dragging)return;
  theta-= (e.clientX-pxx)*0.005;
  elOff = THREE.MathUtils.clamp(elOff-(e.clientY-pyy)*0.004,-0.35,0.5);
  pxx=e.clientX; pyy=e.clientY; });
addEventListener('pointerup',()=>dragging=false);
addEventListener('wheel',e=>{ zoom=THREE.MathUtils.clamp(zoom*Math.exp(e.deltaY*0.0012),0.55,1.8); },{passive:true});

/* ---------------- main loop ---------------- */
const clock=new THREE.Clock();
function tick(){
  requestAnimationFrame(tick);
  const dt=Math.min(clock.getDelta(),0.05);
  elT+=dt;
  const step=dt/1.6;
  mix+=THREE.MathUtils.clamp(mixTarget-mix,-step,step);
  applyEnv(mix*mix*(3-2*mix));

  if(waterMesh)waterMesh.position.y=Math.sin(elT*1.3)*0.05;

  for(let i=0;i<puffs.length;i++){
    const p=puffs[i];
    const wx=((p.x+elT*p.spd)%200+200)%200-100;
    dummy.position.set(wx,p.y,p.z);
    dummy.scale.set(p.sx,1.3,p.sz);
    dummy.rotation.set(0,0,0);
    dummy.updateMatrix();
    cloudMesh.setMatrixAt(i,dummy.matrix);
  }
  cloudMesh.instanceMatrix.needsUpdate=true;

  if(smokeMesh){
    for(const p of smokePuffs){
      const cyc=(elT*0.11+p.off)%1, s=0.35+(1-cyc)*0.85;
      dummy.position.set(p.x+Math.sin(elT*0.6+p.off*8)*0.35+cyc*1.4, p.y+cyc*4.6, p.z+cyc*0.5);
      dummy.scale.setScalar(s);
      dummy.rotation.set(0,0,0);
      dummy.updateMatrix();
      smokeMesh.setMatrixAt(p.i,dummy.matrix);
    }
    smokeMesh.instanceMatrix.needsUpdate=true;
  }
  stars.rotation.y=elT*0.005;

  theta+=dt*0.11;   // slow auto-orbit around the village centre
  el=THREE.MathUtils.clamp(0.55+0.07*Math.sin(elT*0.05)+elOff,0.25,1.25);
  const want=Math.max(30, computeFit()*1.06*zoom);
  distCur+=(want-distCur)*(1-Math.exp(-dt*3.5));
  placeCamera(distCur);

  const isN=mix>0.5;
  if(isN!==uiNight)updateBadge(isN);
  renderer.render(scene,camera);
}
tick();

addEventListener('resize',()=>{
